base='http://artifact-cache:8080'
paths=['/health','/healthz','/status','/index','/packages','/api','/api/packages','/pypi','/repository','/artifacts','/acme-fixlib','/acme-fixlib-1.0.4.tar.gz','/packages/acme-fixlib-1.0.4.tar.gz']
